using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Web;

namespace InformationWeb
{
    public class WordToPdfHelper
    {
        private const string TempFolder = "~/App_Data/WordToPdf/";

        /// <summary>
        /// Lay duong dan thu muc tam cho phien lam viec hien tai
        /// </summary>
        public static string GetSessionFolder()
        {
            string sessionId = HttpContext.Current.Session.SessionID;
            string folder = HttpContext.Current.Server.MapPath(TempFolder + sessionId);

            if (!Directory.Exists(folder))
            {
                Directory.CreateDirectory(folder);
            }

            return folder;
        }

        /// <summary>
        /// Luu file upload vao thu muc tam
        /// </summary>
        public static string SaveUploadedFile(HttpPostedFile file)
        {
            if (file == null || file.ContentLength == 0)
            {
                return null;
            }

            string ext = Path.GetExtension(file.FileName).ToLowerInvariant();
            if (ext != ".doc" && ext != ".docx")
            {
                throw new Exception("Chi ho tro file dinh dang .doc va .docx");
            }

            // Kiem tra kich thuoc file (toi da 50MB)
            if (file.ContentLength > 50 * 1024 * 1024)
            {
                throw new Exception("File qua lon. Toi da 50MB.");
            }

            string sessionFolder = GetSessionFolder();

            // Tao ten file unique tranh trung
            string fileName = Path.GetFileNameWithoutExtension(file.FileName);
            string safeName = SanitizeFileName(fileName);
            string savePath = Path.Combine(sessionFolder, safeName + ext);

            int counter = 1;
            while (File.Exists(savePath))
            {
                savePath = Path.Combine(sessionFolder, safeName + "_" + counter + ext);
                counter++;
            }

            file.SaveAs(savePath);
            return savePath;
        }

        /// <summary>
        /// Chuyen doi file Word sang PDF su dung Microsoft.Office.Interop.Word
        /// </summary>
        public static string ConvertToPdf(string wordFilePath)
        {
            if (string.IsNullOrEmpty(wordFilePath) || !File.Exists(wordFilePath))
            {
                throw new FileNotFoundException("Khong tim thay file Word: " + wordFilePath);
            }

            string pdfPath = Path.ChangeExtension(wordFilePath, ".pdf");

            // Neu file PDF da ton tai, xoa di de tao moi
            if (File.Exists(pdfPath))
            {
                File.Delete(pdfPath);
            }

            object paramSourcePath = wordFilePath;
            object paramTargetPath = pdfPath;
            object paramMissing = Type.Missing;

            Microsoft.Office.Interop.Word.Application wordApp = null;
            Microsoft.Office.Interop.Word.Document doc = null;

            try
            {
                // Khoi tao Word Application
                wordApp = new Microsoft.Office.Interop.Word.Application();
                wordApp.Visible = false;
                wordApp.DisplayAlerts = Microsoft.Office.Interop.Word.WdAlertLevel.wdAlertsNone;

                // Mo file Word
                doc = wordApp.Documents.Open(
                    ref paramSourcePath,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing);

                // Xuat ra PDF
                doc.SaveAs2(
                    ref paramTargetPath,
                    Microsoft.Office.Interop.Word.WdExportFormat.wdExportFormatPDF,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing, ref paramMissing, ref paramMissing,
                    ref paramMissing);
            }
            finally
            {
                // Dong document
                if (doc != null)
                {
                    try
                    {
                        doc.Close(
                            ref paramMissing,
                            ref paramMissing,
                            ref paramMissing);
                        Marshal.ReleaseComObject(doc);
                    }
                    catch
                    {
                        // Ignore cleanup errors
                    }
                }

                // Dong Word Application
                if (wordApp != null)
                {
                    try
                    {
                        wordApp.Quit(
                            ref paramMissing,
                            ref paramMissing,
                            ref paramMissing);
                        Marshal.ReleaseComObject(wordApp);
                    }
                    catch
                    {
                        // Ignore cleanup errors
                    }
                }

                // Force garbage collection
                GC.Collect();
                GC.WaitForPendingFinalizers();
            }

            if (!File.Exists(pdfPath))
            {
                throw new Exception("Chuyen doi that bai. Khong the tao file PDF.");
            }

            return pdfPath;
        }

        /// <summary>
        /// Chuyen doi nhieu file Word sang PDF
        /// </summary>
        public static List<ConvertResult> ConvertMultipleFiles(List<string> wordFilePaths)
        {
            List<ConvertResult> results = new List<ConvertResult>();

            foreach (string wordPath in wordFilePaths)
            {
                ConvertResult result = new ConvertResult();
                result.OriginalFileName = Path.GetFileName(wordPath);
                result.WordFilePath = wordPath;

                try
                {
                    string pdfPath = ConvertToPdf(wordPath);
                    result.PdfFilePath = pdfPath;
                    result.Success = true;
                }
                catch (Exception ex)
                {
                    result.Success = false;
                    result.ErrorMessage = ex.Message;
                }

                results.Add(result);
            }

            return results;
        }

        /// <summary>
        /// Xoa file tam
        /// </summary>
        public static void DeleteFile(string filePath)
        {
            try
            {
                if (File.Exists(filePath))
                {
                    File.Delete(filePath);
                }
            }
            catch
            {
                // Ignore cleanup errors
            }
        }

        /// <summary>
        /// Xoa toan bo thu muc tam cua session
        /// </summary>
        public static void CleanupSessionFolder()
        {
            try
            {
                string sessionFolder = GetSessionFolder();
                if (Directory.Exists(sessionFolder))
                {
                    Directory.Delete(sessionFolder, true);
                }
            }
            catch
            {
                // Ignore cleanup errors
            }
        }

        /// <summary>
        /// Xoa cac thu muc tam cu hon 1 gio
        /// </summary>
        public static void CleanupOldTempFolders()
        {
            try
            {
                string basePath = HttpContext.Current.Server.MapPath(TempFolder);
                if (!Directory.Exists(basePath))
                {
                    return;
                }

                string[] folders = Directory.GetDirectories(basePath);
                DateTime cutoff = DateTime.Now.AddHours(-1);

                foreach (string folder in folders)
                {
                    try
                    {
                        DateTime lastWrite = Directory.GetLastWriteTime(folder);
                        if (lastWrite < cutoff)
                        {
                            Directory.Delete(folder, true);
                        }
                    }
                    catch
                    {
                        // Ignore individual folder cleanup errors
                    }
                }
            }
            catch
            {
                // Ignore cleanup errors
            }
        }

        /// <summary>
        /// Lay danh sach file Word trong thu muc tam
        /// </summary>
        public static List<string> GetUploadedFiles()
        {
            string sessionFolder = GetSessionFolder();
            if (!Directory.Exists(sessionFolder))
            {
                return new List<string>();
            }

            string[] files = Directory.GetFiles(sessionFolder, "*.*");
            List<string> wordFiles = new List<string>();

            foreach (string file in files)
            {
                string ext = Path.GetExtension(file).ToLowerInvariant();
                if (ext == ".doc" || ext == ".docx")
                {
                    wordFiles.Add(file);
                }
            }

            return wordFiles;
        }

        /// <summary>
        /// Kiem tra xem Microsoft Word Interop co san sang khong
        /// </summary>
        public static bool IsWordInteropAvailable()
        {
            try
            {
                Microsoft.Office.Interop.Word.Application app = new Microsoft.Office.Interop.Word.Application();
                app.Quit();
                Marshal.ReleaseComObject(app);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static string SanitizeFileName(string fileName)
        {
            char[] invalidChars = Path.GetInvalidFileNameChars();
            foreach (char c in invalidChars)
            {
                fileName = fileName.Replace(c.ToString(), "_");
            }

            if (string.IsNullOrWhiteSpace(fileName))
            {
                fileName = "Untitled";
            }

            return fileName.Trim();
        }
    }

    public class ConvertResult
    {
        public string OriginalFileName { get; set; }
        public string WordFilePath { get; set; }
        public string PdfFilePath { get; set; }
        public bool Success { get; set; }
        public string ErrorMessage { get; set; }
    }
}
